        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax on an amount in integer cents, banker's rounded to whole cents."""
    exact = Decimal(amount_cents) * Decimal(str(rate))
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))


def invoice_tax(lines, rate):
    """Total tax in cents: round each line's tax separately, then sum."""
    return sum(tax_for(line["quantity"] * line["unit_cents"], rate) for line in lines)
